cd /workspace/docs && python3 - <<'EOF'
import glob, re, os, sys

ok = True
for f in sorted(glob.glob('*.rst')):
    text = open(f).read()
    lines = text.splitlines()
    # check literal block '::' is followed by blank + indented block or end
    for i, ln in enumerate(lines):
        if ln.rstrip().endswith('::') and not ln.lstrip().startswith('..'):
            j = i + 1
            if j < len(lines) and lines[j].strip() == '':
                j += 1
                if j < len(lines) and lines[j].strip() and not lines[j].startswith((' ', '\t')):
                    print(f'{f}:{i+1} "::" not followed by indented block'); ok = False
    # check toctree entries exist
    m = re.search(r'\.\. toctree::.*?\n(.*?)(?=\n\S|\Z)', text, re.S)
    if m:
        for entry in re.findall(r'^\s{3}(\S+)\s*$', m.group(1), re.M):
            if entry.startswith(':') : continue
            if not os.path.exists(entry + '.rst'):
                print(f'{f}: toctree entry missing file: {entry}'); ok = False
    # balanced directive indentation: every automodule/toctree has blank line after options - skip
    # check title underline lengths
    for i in range(len(lines)-1):
        if lines[i].strip() and re.fullmatch(r'[=\-*~^"#+]{3,}', lines[i+1].strip() or ' ') and len(lines[i+1].strip()) < len(lines[i].strip()):
            print(f'{f}:{i+2} underline shorter than title: {lines[i]!r}'); ok = False
print('ROUGH RST CHECK:', 'PASS' if ok else 'FAIL')
EOF
